const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let current='dashboard',cache={};
const salesBillTemplates=[{id:1,name:'Emirates Classic',header:'#087451',paper:'#ffffff',accent:'#087451'},{id:2,name:'Executive Navy',header:'#193b67',paper:'#f2f5f8',accent:'#193b67'},{id:3,name:'Smart Green',header:'#ffffff',paper:'#ffffff',accent:'#0b7657'},{id:4,name:'Office Slate',header:'#5b626a',paper:'#ffffff',accent:'#5b626a'},{id:5,name:'Typing Center',header:'#0b7657',paper:'#ffffff',accent:'#0b7657'}];
async function api(action,options={}){const res=await fetch(`api.php?action=${action}`,{...options,credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF':window.FORA.csrf,...options.headers},body:options.body?JSON.stringify(options.body):undefined});const contentType=res.headers.get('content-type')||'';if(!contentType.toLowerCase().includes('application/json')){if(res.redirected&&/login\.php/i.test(res.url)){window.location.assign('login.php');throw Error('Your login session expired. Please sign in again.')}if(res.status===419){throw Error('Your session expired. Refresh the page and try again.')}throw Error('The server returned a page instead of inventory data. Refresh the page and sign in again if asked.')}const data=await res.json();if(!res.ok||data.error)throw Error(data.error||'Something went wrong');return data}
const money=n=>new Intl.NumberFormat('en-AE',{style:'currency',currency:'AED',maximumFractionDigits:0}).format(n||0),date=s=>s?new Date(s+'T00:00:00').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}):'—';
const dateInput=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
function toast(msg,bad=false){let t=$('#toast');t.textContent=msg;t.classList.toggle('bad',bad);t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3000)}
function field(label,name,type='text',opts={}){if(type==='select')return `<label>${label}<select name="${name}" ${opts.required===false?'':'required'}>${(opts.options||[]).map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}</select></label>`;if(type==='combo')return `<label>${label}<input name="${name}" list="options-${name}" ${opts.required===false?'':'required'} autocomplete="off"><datalist id="options-${name}">${(opts.options||[]).map(v=>`<option value="${esc(v)}"></option>`).join('')}</datalist></label>`;return `<label>${label}<input name="${name}" type="${type}" ${opts.required===false?'':'required'} ${opts.step?'step="'+opts.step+'"':''} ${opts.min!==undefined?'min="'+opts.min+'"':''} ${opts.readonly?'readonly':''} placeholder="${opts.placeholder||''}"></label>`}
function shell(title,eyebrow,body,action=''){return `<div class="section-head professional-page-head"><div><span class="eyebrow">${eyebrow}</span><h2>${title}</h2></div>${action}</div>${body}`}
async function go(view){current=view;document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view===view));let labels={dashboard:'OVERVIEW',properties:'PROPERTIES',details:'UNIT DETAILS',tenancies:'RENT A ROOM',tenants:'TENANT DIRECTORY',renewals:'RENEWALS',cancellations:'CANCELLATIONS',cheques:'CHEQUE REGISTER',staff:'STAFF & ACCESS'};$('#crumb').textContent=labels[view]||view.toUpperCase();$('#page-title').innerHTML=({dashboard:`Good morning, ${esc(window.FORA.user.name.split(' ')[0])} <span class="wave">✳</span>`,properties:'Your properties',details:'Unit details',tenancies:'Rent a room',tenants:'Tenant directory',renewals:'Renew a tenancy',cancellations:'Cancel a tenancy',cheques:'Cheque register',staff:'Staff & access'})[view];$('#content').innerHTML='<div class="loading">Loading workspace…</div>';try{await ({dashboard:dashboard,properties:properties,details:details,tenancies:tenancies,tenants:tenants,renewals:renewals,cancellations:cancellations,cheques:cheques,staff:staff}[view]||dashboard)()}catch(e){$('#content').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}" class="empty-cell">Nothing to show yet</td></tr>`}</tbody></table></div>`}
async function dashboard(){let d=await api('dashboard');$('#content').innerHTML=`<div class="welcome-band"><div><span class="eyebrow">PORTFOLIO SNAPSHOT</span><h2>Your real estate, <em>in good order.</em></h2><p>Track occupancy, tenants and upcoming renewals in one place.</p></div><div class="welcome-orbit">F<span>+</span></div></div><div class="stat-grid">${[['Properties',d.properties,'⌂','properties'],['Active tenants',d.tenants,'♙','tenants'],['Available units',d.vacant,'▦','details'],['Pending cheques',d.cheques,'▤','cheques']].map(([a,b,c,v])=>`<button class="stat-card" data-go="${v}"><span>${a}<i>${c}</i></span><strong>${b}</strong><small>View ${a.toLowerCase()} <b>↗</b></small></button>`).join('')}</div><div class="dashboard-grid"><section class="panel">${shell('Recent tenancies','LATEST ACTIVITY','')}<div class="table-responsive">${table(['TENANT','PROPERTY / UNIT','TERM','YEARLY RENT','STATUS'],d.recent.map(x=>`<tr><td><b>${esc(x.tenant_name)}</b></td><td>${esc(x.property_name)}<small class="sub-cell">Unit ${esc(x.room_number)}</small></td><td>${date(x.start_date)} – ${date(x.end_date)}</td><td>${money(x.yearly_rent)}</td><td><span class="pill ${x.status==='Active'?'green':'gray'}">${esc(x.status)}</span></td></tr>`).join(''))}</div></section><aside class="panel renewal-panel"><span class="eyebrow">COMING UP</span><div class="renewal-count">${d.expiring}<span>within 60 days</span></div><p>Tenancies approaching their end date.</p><button class="text-button" data-go="renewals">Review renewals <b>→</b></button><div class="panel-rule"></div><div class="mini-note">Keep your portfolio current with timely renewals and clear cheque records.</div></aside></div>`}
async function properties(){let rows=await api('properties');cache.properties=rows;let filter=$('#property-filter')?.value||'';let view=rows.filter(x=>[x.name,x.owner_name,x.emirate,x.area].join(' ').toLowerCase().includes(filter.toLowerCase()));$('#content').innerHTML=shell('Buildings & assets','PORTFOLIO',`<div class="toolbar"><input id="property-filter" class="search" placeholder="Search owner, area, emirate or name" value="${esc(filter)}"><select id="property-emirate" class="search"><option value="">All emirates</option>${[...new Set(rows.map(x=>x.emirate))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></div>${table(['PROPERTY','CODE','LOCATION','OWNER','TYPE','UNITS','AVAILABLE'],view.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td class="mono">${esc(x.code)}</td><td>${esc(x.area)}, ${esc(x.emirate)}</td><td>${esc(x.owner_name)}<small class="sub-cell">${esc(x.owner_contact)}</small></td><td>${esc(x.type)}</td><td>${x.rooms||0}</td><td><span class="pill blue">${x.vacant||0} vacant</span></td></tr>`).join(''))}`,`<button class="button button-dark" data-modal="property">＋ Add property</button>`);$('#property-filter').oninput=e=>{let val=e.target.value;properties().then(()=>$('#property-filter').value=val)};$('#property-emirate').onchange=e=>{$('#property-filter').value=e.target.value;$('#property-filter').dispatchEvent(new Event('input'))}}
async function details(){let units=await api('units');$('#content').innerHTML=shell('Rooms, suites & unit inventory','UNIT DETAILS',`${table(['PROPERTY','ROOM','CONFIGURATION','BATHROOMS','FLOOR','OCCUPANCY','STATUS'],units.map(x=>`<tr><td><b>${esc(x.property_name)}</b><small class="sub-cell">${esc(x.area)}, ${esc(x.emirate)}</small></td><td>${esc(x.room_number)}</td><td>${esc(x.bedrooms)}</td><td>${x.bathrooms}</td><td>${esc(x.floor_label||'—')}</td><td>${esc(x.occupancy)}</td><td><span class="pill ${x.occupied?'amber':'green'}">${x.occupied?'Occupied':'Available'}</span></td></tr>`).join(''))}`,`<button class="button button-dark" data-modal="unit">＋ Add unit</button>`)}
async function tenants(){let all=await api('tenants');cache.tenantRows=all;let q=$('#tenant-filter')?.value||'';let rows=all.filter(x=>[x.name,x.contact,x.property_name,x.area,x.emirate,x.end_date].join(' ').toLowerCase().includes(q.toLowerCase()));$('#content').innerHTML=shell('People across your portfolio','TENANT DIRECTORY',`<div class="toolbar"><input id="tenant-filter" class="search" placeholder="Search name, mobile, property, area, emirate or expiry" value="${esc(q)}"></div>${table(['TENANT · CLICK FOR HISTORY','CONTACT / ID','PROPERTY','PURPOSE','RENT','TERM','STATUS'],rows.map(x=>`<tr><td><button class="history-link" data-history="${x.id}">${esc(x.name)}</button><small class="sub-cell">Agreement #${x.tenancy_id||'—'}</small></td><td>${esc(x.contact)}<small class="sub-cell">${esc(x.identity_number||'')}</small></td><td>${esc(x.property_name||'—')}<small class="sub-cell">${esc(x.area||'')} ${esc(x.emirate||'')}</small></td><td>${esc(x.purpose||'—')}</td><td>${x.yearly_rent?money(x.yearly_rent):'—'}</td><td>${date(x.start_date)} – ${date(x.end_date)}</td><td><span class="pill ${x.status==='Active'?'green':'gray'}">${esc(x.status||'No tenancy')}</span></td></tr>`).join(''))}`);$('#tenant-filter').oninput=e=>{let v=e.target.value;tenants().then(()=>$('#tenant-filter').value=v)}}
async function tenancies(){let [units,people]=await Promise.all([api('units'),api('tenants')]);cache.units=units;let active=people.filter(x=>x.status==='Active');$('#content').innerHTML=shell('Create or renew an agreement','RENT A ROOM',`<form id="tenancy-form" class="form-card"><div class="form-grid"><label>Agreement type<select name="agreement_type"><option value="New">New tenancy</option><option value="Renewal">Renewal</option></select></label><label id="renew-source-label" class="hidden">Renew current tenancy<select name="renewal_of"><option value="">Select tenant and current agreement</option>${active.map(x=>`<option value="${x.tenancy_id}">${esc(x.name)} · ${esc(x.contact)} · ${esc(x.property_name)} / ${esc(x.room_number)} · ends ${date(x.end_date)}</option>`).join('')}</select></label></div><div class="form-section-title">01 <span>PROPERTY & TENANT</span></div><div class="form-grid">${field('Building / property','unit_id','select',{options:units.map(x=>`${x.id}|${x.property_name} · ${x.room_number}${x.occupied?' · OCCUPIED':''}`)})}${field('Room number','room_show','text',{placeholder:'Select building first'})}${field('Tenant name','name')}${field('Mobile / contact','contact','tel')}${field('Nationality','nationality')}${field('VAT ID','vat_id','text',{required:false})}${field('ID / passport number','identity_number')}${field('Purpose','purpose','select',{options:['Family','Bachelor']})}</div><div class="form-section-title">02 <span>DATES, RENT & PAYMENT</span></div><div class="form-grid">${field('Start date','start_date','date')}${field('End date','end_date','date')}${field('Free months','free_months','number',{min:0})}${field('Yearly rent (AED)','yearly_rent','number',{step:'0.01',min:0})}${field('Payment mode','payment_mode','select',{options:['Cash','Cheque']})}${field('Commission (AED)','commission_amount','number',{step:'0.01',min:0,required:false})}${field('Security deposit (AED)','security_amount','number',{step:'0.01',min:0,required:false})}${field('SEWA account','sewa_account','text',{required:false})}</div><div id="cheque-box" class="cheque-box hidden"><div class="inline-head"><b>Cheque schedule</b><button type="button" class="text-button" id="add-cheque">＋ Add cheque</button></div><div class="quiet">Enter each cheque for the new agreement and its scheduled date.</div><div id="cheque-list"></div></div><div class="form-grid"><label class="span-2">Notes<textarea name="notes" rows="3" placeholder="Additional tenancy notes"></textarea></label><label class="upload-field span-2">Signed tenancy agreement <input type="file" name="agreement" accept="image/*,application/pdf"><small>Optional · PDF, JPG, PNG or WebP · max 8 MB</small></label></div><div class="form-actions"><button class="button button-dark">Save tenancy <span>→</span></button></div></form>`);let f=$('#tenancy-form'),sel=f.elements.unit_id;function setUnits(allowOccupied){sel.innerHTML='<option value="">Select '+(allowOccupied?'current unit':'available unit')+'</option>'+units.filter(x=>allowOccupied||!x.occupied).map(x=>`<option value="${x.id}">${esc(x.property_name)} · ${esc(x.room_number)} (${esc(x.area)})${x.occupied?' · Occupied':''}</option>`).join('')}setUnits(false);$('#cheque-list').innerHTML='';sel.onchange=()=>{let x=units.find(u=>u.id==sel.value);f.elements.room_show.value=x?`${x.property_name} · ${x.room_number}`:''};f.elements.payment_mode.onchange=e=>$('#cheque-box').classList.toggle('hidden',e.target.value!=='Cheque');f.elements.agreement_type.onchange=()=>{let renewing=f.elements.agreement_type.value==='Renewal';$('#renew-source-label').classList.toggle('hidden',!renewing);f.elements.renewal_of.required=renewing;f.elements.name.readOnly=renewing;setUnits(renewing);if(!renewing){f.elements.renewal_of.value='';f.elements.unit_id.value='';f.elements.room_show.value='';f.elements.name.value='';f.elements.contact.value='';f.elements.nationality.value='';f.elements.vat_id.value='';f.elements.identity_number.value=''}};f.elements.renewal_of.onchange=()=>{let old=active.find(x=>x.tenancy_id==f.elements.renewal_of.value);if(!old)return;f.elements.unit_id.value=old.unit_id;f.elements.room_show.value=`${old.property_name} · ${old.room_number}`;f.elements.name.value=old.name;f.elements.contact.value=old.contact;f.elements.nationality.value=old.nationality||'';f.elements.vat_id.value=old.vat_id||'';f.elements.identity_number.value=old.identity_number||'';f.elements.purpose.value=old.purpose;let startDate=new Date(old.end_date+'T00:00:00');startDate.setDate(startDate.getDate()+1);f.elements.start_date.value=startDate.toISOString().slice(0,10);let endDate=new Date(startDate);endDate.setFullYear(endDate.getFullYear()+1);endDate.setDate(endDate.getDate()-1);f.elements.end_date.value=endDate.toISOString().slice(0,10);f.elements.free_months.value=old.free_months||0;f.elements.yearly_rent.value=old.yearly_rent;f.elements.payment_mode.value=old.payment_mode;f.elements.commission_amount.value=old.commission_amount||0;f.elements.security_amount.value=old.security_amount||0;f.elements.sewa_account.value=old.sewa_account||'';f.elements.notes.value=old.notes||'';$('#cheque-box').classList.toggle('hidden',old.payment_mode!=='Cheque')};$('#add-cheque').onclick=()=>addCheque();f.onsubmit=saveTenancy}
function addCheque(){let row=document.createElement('div');row.className='cheque-row form-grid';row.innerHTML=`${field('Number','number')}${field('Bank','bank')}${field('Cheque date','date','date')}${field('Amount (AED)','amount','number',{step:'0.01',min:0})}${field('Holder name','holder','text',{required:false})}<button type="button" class="remove-cheque">Remove</button>`;row.querySelector('.remove-cheque').onclick=()=>row.remove();$('#cheque-list').append(row)}
async function saveTenancy(e){e.preventDefault();let f=e.currentTarget,fd=new FormData(f);let cheques=[...$('#cheque-list').querySelectorAll('.cheque-row')].map(r=>Object.fromEntries([...r.querySelectorAll('[name]')].map(i=>[i.name,i.value])));try{let res=await fetch('api.php?action=tenancy',{method:'POST',headers:{'X-CSRF':window.FORA.csrf},body:fdWithCheques(fd,cheques)});let j=await res.json();if(!res.ok||j.error)throw Error(j.error);toast('Tenancy saved.');go('tenants')}catch(err){toast(err.message,true)}}
function fdWithCheques(fd,cheques){fd.set('payload',JSON.stringify({cheques}));return fd}
async function cheques(){let rows=await api('cheques');$('#content').innerHTML=shell('Track scheduled rent payments','CHEQUE REGISTER',`<div class="toolbar"><input id="cheque-filter" class="search" placeholder="Search bank, tenant or number"><span class="quiet">${rows.filter(x=>!x.cleared).length} uncleared</span></div>${table(['CHEQUE','TENANT','PROPERTY','BANK','DATE','AMOUNT','HOLDER','STATUS'],rows.map(x=>`<tr><td class="mono">${esc(x.cheque_number)}</td><td>${esc(x.tenant_name)}</td><td>${esc(x.property_name)}</td><td>${esc(x.bank_name)}</td><td>${date(x.cheque_date)}</td><td>${money(x.amount)}</td><td>${esc(x.holder_name)}</td><td><label class="check-label"><input type="checkbox" data-cheque="${x.id}" ${x.cleared?'checked':''}> Cleared</label></td></tr>`).join(''))}`);document.querySelectorAll('[data-cheque]').forEach(c=>c.onchange=async()=>{try{await api('clear-cheque',{method:'POST',body:{id:c.dataset.cheque,cleared:c.checked}});toast('Cheque status updated.')}catch(e){c.checked=!c.checked;toast(e.message,true)}});$('#cheque-filter').oninput=e=>document.querySelectorAll('tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase()))}
async function renewals(){let rows=(await api('tenants')).filter(t=>t.status==='Renewed'||t.previous_tenancy_id);$('#content').innerHTML=shell('Renewals are saved as separate agreements','RENEWAL HISTORY',`<div class="notice">Each renewal is a new tenancy record with its own dates, rent and cheques. Earlier agreements remain available in Tenant Details.</div>${table(['TENANT','PROPERTY / UNIT','AGREEMENT DATES','YEARLY RENT','RECORD'],rows.map(x=>`<tr><td><b>${esc(x.name)}</b><small class="sub-cell">${esc(x.contact)}</small></td><td>${esc(x.property_name)} · ${esc(x.room_number)}</td><td>${date(x.start_date)} – ${date(x.end_date)}</td><td>${money(x.yearly_rent)}</td><td><span class="pill ${x.status==='Active'?'green':'gray'}">${x.status==='Renewed'?'Previous term':'Current renewal'}</span></td></tr>`).join(''))}`,`<button class="button button-dark" data-go="tenancies">＋ Start renewal</button>`)}
async function cancellations(){let people=(await api('tenants')).filter(t=>t.status==='Active');$('#content').innerHTML=shell('Close a tenancy with a clear record','CANCEL TENANCY',`<div class="notice warning">Cancellation is blocked when uncleared cheques remain due on or before the cancellation date. Confirm the tenant balance is settled.</div><form id="cancel-form" class="form-card"><div class="form-grid"><label class="span-2">Active tenancy<select name="tenancy_id" required><option value="">Select tenant</option>${people.map(p=>`<option value="${p.tenancy_id}">${esc(p.name)} · ${esc(p.contact)} · ${esc(p.property_name)} / ${esc(p.room_number)} · ends ${date(p.end_date)}</option>`).join('')}</select></label>${field('Cancellation date','cancelled_at','date')}<label class="span-2"><input type="checkbox" name="balance_settled" required> I confirm outstanding rent and tenant balances are settled.</label><label class="upload-field">Cancelled agreement<input type="file" name="cancel_agreement" accept="image/*,application/pdf"><small>Optional · PDF or image</small></label><label class="upload-field">SEWA final bill<input type="file" name="sewa_bill" accept="image/*,application/pdf"><small>Optional · PDF or image</small></label></div><div class="form-actions"><button class="button button-dark">Check & cancel tenancy <span>→</span></button></div></form>`);$('#cancel-form').onsubmit=async e=>{e.preventDefault();let f=e.currentTarget,fd=new FormData(f);fd.set('payload',JSON.stringify({tenancy_id:fd.get('tenancy_id'),cancelled_at:fd.get('cancelled_at'),balance_settled:fd.get('balance_settled')==='on'}));try{let r=await fetch('api.php?action=cancel',{method:'POST',headers:{'X-CSRF':window.FORA.csrf},body:fd}),j=await r.json();if(!r.ok||j.error)throw Error(j.error);toast('Tenancy cancelled.');go('tenants')}catch(x){toast(x.message,true)}}}
async function staff(){let users=await api('staff');$('#content').innerHTML=shell('People with workspace access','TEAM',`<form id="staff-form" class="form-card compact-form"><div class="form-grid">${field('Full name','name')}${field('Username','username')}${field('Temporary password','password','password')}${field('Role','role','select',{options:['staff','admin']})}</div><div class="form-actions"><button class="button button-dark">＋ Create account</button></div></form><div class="panel table-panel">${table(['NAME','USERNAME','ROLE','STATUS','JOINED'],users.map(u=>`<tr><td><b>${esc(u.name)}</b></td><td>${esc(u.username)}</td><td>${esc(u.role)}</td><td><span class="pill ${u.active?'green':'gray'}">${u.active?'Active':'Disabled'}</span></td><td>${date(u.created_at?.slice(0,10))}</td></tr>`).join(''))}</div>`);$('#staff-form').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.currentTarget));try{await api('staff',{method:'POST',body:d});toast('Staff account created.');staff()}catch(x){toast(x.message,true)}}}
async function modal(type){if(type==='property')$('#modal-root').innerHTML=`<div class="modal-backdrop"><form id="modal-form" class="modal"><button type="button" class="modal-close">×</button><span class="eyebrow">PORTFOLIO</span><h2>Add a property</h2><div class="form-grid">${field('Property name','name')}${field('Property code','code')}${field('Emirate','emirate','select',{options:['Abu Dhabi','Dubai','Sharjah','Ajman','Umm Al Quwain','Ras Al Khaimah','Fujairah']})}${field('Area','area')}${field('Owner name','owner_name')}${field('Owner contact','owner_contact','tel',{required:false})}${field('Property type','type','select',{options:['Residential','Commercial','Land','Shed','Warehouse','Other']})}<label class="span-2">Address<textarea name="address" rows="2"></textarea></label></div><div class="form-actions"><button class="button button-dark">Save property</button></div></form></div>`;
if(type==='unit'){let props=cache.properties||await api('properties');$('#modal-root').innerHTML=`<div class="modal-backdrop"><form id="modal-form" class="modal"><button type="button" class="modal-close">×</button><span class="eyebrow">UNIT INVENTORY</span><h2>Add a room or unit</h2><div class="form-grid"><label class="span-2">Property<select name="property_id" required>${props.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.code)}</option>`).join('')}</select></label>${field('Room number','room_number')}${field('Bedrooms','bedrooms','select',{options:['Studio',...Array.from({length:10},(_,i)=>`${i+1} BHK`)]})}${field('Bathrooms','bathrooms','number',{min:1})}${field('Floor','floor_label','text',{required:false})}${field('Occupancy','occupancy','select',{options:['Family','Bachelor','Both']})}</div><div class="form-actions"><button class="button button-dark">Save unit</button></div></form></div>`}
$('#modal-root').querySelector('.modal-close').onclick=()=>$('#modal-root').innerHTML='';$('#modal-root').querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))$('#modal-root').innerHTML=''};$('#modal-form').onsubmit=async e=>{e.preventDefault();try{await api(type,{method:'POST',body:Object.fromEntries(new FormData(e.currentTarget))});$('#modal-root').innerHTML='';toast(type==='property'?'Property saved.':'Unit saved.');go(type==='property'?'properties':'details')}catch(x){toast(x.message,true)}}}
document.addEventListener('click',e=>{let nav=e.target.closest('[data-view]'),action=e.target.closest('[data-go]'),m=e.target.closest('[data-modal]');if(nav)go(nav.dataset.view);if(action)go(action.dataset.go);if(m)modal(m.dataset.modal)});$('#mobile-menu').onclick=()=>document.body.classList.toggle('sidebar-open');$('#today').textContent=new Intl.DateTimeFormat('en-AE',{day:'2-digit',month:'long',year:'numeric'}).format(new Date());
async function shop(){ $('#content').innerHTML=shell('A separate place for your next category','SHOP',`<div class="shop-placeholder"><div class="welcome-orbit">S<span>+</span></div><div><span class="eyebrow">CATEGORY READY</span><h2>Shop management can live here.</h2><p>This workspace is reserved for your Shop category. Your property and tenancy records stay grouped under Real Estate.</p></div></div>`)}
async function go(view){current=view;document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view===view));let labels={dashboard:'OVERVIEW',properties:'PROPERTIES',details:'UNIT DETAILS',tenancies:'RENT A ROOM',tenants:'TENANT DIRECTORY',renewals:'RENEWAL HISTORY',cancellations:'CANCELLATIONS',cheques:'CHEQUE REGISTER',staff:'STAFF & ACCESS',shop:'SHOP'};let titles={dashboard:`Good morning, ${esc(window.FORA.user.name.split(' ')[0])} <span class="wave">✳</span>`,properties:'Your properties',details:'Unit details',tenancies:'Rent a room',tenants:'Tenant directory',renewals:'Renewal history',cancellations:'Cancel tenancy',cheques:'Cheque register',staff:'Staff & access',shop:'Shop workspace'};$('#crumb').textContent=labels[view]||view.toUpperCase();$('#page-title').innerHTML=titles[view]||view;$('#content').innerHTML='<div class="loading">Loading workspace…</div>';try{await ({dashboard,properties,details,tenancies,tenants,renewals,cancellations,cheques,staff,shop}[view]||dashboard)();if(view==='tenancies'){cache.tenantRows=await api('tenants');let f=$('#tenancy-form');f.elements.renewal_of.addEventListener('change',()=>{let old=(cache.tenantRows||[]).find(x=>x.tenancy_id==f.elements.renewal_of.value);if(!old)return;let start=new Date(old.end_date+'T00:00:00');start.setDate(start.getDate()+1);f.elements.start_date.value=dateInput(start);let end=new Date(start);end.setFullYear(end.getFullYear()+1);end.setDate(end.getDate()-1);f.elements.end_date.value=dateInput(end)})}}catch(e){$('#content').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
async function showTenantHistory(id){let rows=cache.tenantRows||await api('tenants'),records=rows.filter(x=>x.id==id&&x.tenancy_id).sort((a,b)=>b.start_date.localeCompare(a.start_date));if(!records.length)return;let checks=await api('cheques'),person=records[0];$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal history-modal"><button type="button" class="modal-close">×</button><span class="eyebrow">TENANT RECORD</span><h2>${esc(person.name)}</h2><p class="muted">${esc(person.contact)} · ${esc(person.nationality||'Nationality not recorded')} · ${records.length} agreement${records.length===1?'':'s'} on file</p><div class="history-list">${records.map(r=>{let cs=checks.filter(c=>c.tenancy_id==r.tenancy_id);return `<article class="history-card"><div class="history-card-head"><div><b>${esc(r.property_name)} · Unit ${esc(r.room_number)}</b><small>${date(r.start_date)} – ${date(r.end_date)} · Agreement #${r.tenancy_id}</small></div><span class="pill ${r.status==='Active'?'green':'gray'}">${esc(r.status)}</span></div><div class="history-facts"><span><small>Yearly rent</small><b>${money(r.yearly_rent)}</b></span><span><small>Payment</small><b>${esc(r.payment_mode)}</b></span><span><small>Purpose</small><b>${esc(r.purpose)}</b></span><span><small>Free months</small><b>${esc(r.free_months)}</b></span><span><small>Commission</small><b>${money(r.commission_amount)}</b></span><span><small>Security</small><b>${money(r.security_amount)}</b></span></div>${r.sewa_account?`<p class="history-note">SEWA: ${esc(r.sewa_account)}</p>`:''}${r.notes?`<p class="history-note">${esc(r.notes)}</p>`:''}${cs.length?`<div class="history-cheques"><b>Cheque schedule</b>${cs.map(c=>`<span>${esc(c.cheque_number)} · ${esc(c.bank_name)} · ${date(c.cheque_date)} · ${money(c.amount)} · ${c.cleared?'Cleared':'Pending'}</span>`).join('')}</div>`:'<div class="history-cheques muted">No cheques recorded for this agreement.</div>'}</article>`}).join('')}</div></section></div>`;$('#modal-root').querySelector('.modal-close').onclick=()=>$('#modal-root').innerHTML='';$('#modal-root').querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))$('#modal-root').innerHTML=''}}
document.addEventListener('click',e=>{let b=e.target.closest('[data-history]');if(b)showTenantHistory(b.dataset.history)});

async function tenancies(){
  let units=await api('units');cache.units=units;
  $('#content').innerHTML=shell('Create or renew an agreement','RENT A ROOM',`<form id="tenancy-form" class="form-card">
    <div class="form-grid"><label>Agreement type<select name="agreement_type"><option value="New">New tenancy</option><option value="Renewal">Renewal</option></select></label><div class="code-note">New tenants receive a unique Fora code automatically when the tenancy is saved.</div></div>
    <div id="renew-lookup" class="renew-lookup hidden"><label>Tenant unique code<input name="renewal_code" autocomplete="off" placeholder="e.g. FORA-A12BC34D"></label><button type="button" class="button button-dark" id="lookup-tenant">Find tenant <span>→</span></button><input type="hidden" name="renewal_of"><div id="lookup-status" class="lookup-status span-2">Enter the tenant code to load their latest agreement.</div></div>
    <div class="form-section-title">01 <span>PROPERTY & TENANT</span></div><div class="form-grid">
      ${field('Building / property','unit_id','select',{options:units.map(x=>`${x.id}|${x.property_name} · ${x.room_number}`)})}${field('Room number','room_show','text',{placeholder:'Select building first'})}${field('Tenant name','name')}${field('Mobile / contact','contact','tel')}${field('Nationality','nationality')}${field('VAT ID','vat_id','text',{required:false})}${field('ID / passport number','identity_number')}${field('Purpose','purpose','select',{options:['Family','Bachelor']})}
    </div><div class="form-section-title">02 <span>DATES, RENT & PAYMENT</span></div><div class="form-grid">
      ${field('Start date','start_date','date')}${field('End date','end_date','date')}${field('Free months','free_months','number',{min:0})}${field('Yearly rent (AED)','yearly_rent','number',{step:'0.01',min:0})}${field('Payment mode','payment_mode','select',{options:['Cash','Cheque']})}${field('Commission (AED)','commission_amount','number',{step:'0.01',min:0,required:false})}${field('Security deposit (AED)','security_amount','number',{step:'0.01',min:0,required:false})}${field('SEWA account','sewa_account','text',{required:false})}
    </div><div id="cheque-box" class="cheque-box hidden"><div class="inline-head"><b>New cheque schedule</b><button type="button" class="text-button" id="add-cheque">＋ Add cheque</button></div><div class="quiet">Add the new cheque numbers and payment dates for this agreement.</div><div id="cheque-list"></div></div>
    <div class="form-grid"><label class="span-2">Notes<textarea name="notes" rows="3" placeholder="Additional tenancy notes"></textarea></label><label class="upload-field span-2">Signed tenancy agreement <input type="file" name="agreement" accept="image/*,application/pdf"><small>Optional · PDF, JPG, PNG or WebP · max 8 MB</small></label></div><div class="form-actions"><button class="button button-dark">Save tenancy <span>→</span></button></div>
  </form>`);
  const f=$('#tenancy-form'),unit=f.elements.unit_id;
  function unitsFor(occupied){unit.disabled=false;unit.innerHTML='<option value="">Select '+(occupied?'current':'available')+' unit</option>'+units.filter(x=>occupied||!x.occupied).map(x=>`<option value="${x.id}">${esc(x.property_name)} · ${esc(x.room_number)} (${esc(x.area)})${x.occupied?' · Occupied':''}</option>`).join('')}
  unitsFor(false);$('#cheque-list').innerHTML='';
  unit.onchange=()=>{let x=units.find(u=>u.id==unit.value);f.elements.room_show.value=x?`${x.property_name} · ${x.room_number}`:''};
  f.elements.payment_mode.onchange=e=>$('#cheque-box').classList.toggle('hidden',e.target.value!=='Cheque');
  f.elements.agreement_type.onchange=()=>{let renew=f.elements.agreement_type.value==='Renewal';$('#renew-lookup').classList.toggle('hidden',!renew);f.elements.renewal_code.required=renew;unitsFor(renew);f.elements.renewal_of.value='';f.elements.renewal_code.value='';$('#lookup-status').textContent='Enter the tenant code to load their latest agreement.';$('#lookup-status').className='lookup-status span-2';f.elements.name.readOnly=renew;f.elements.contact.readOnly=renew;f.elements.nationality.readOnly=renew;f.elements.vat_id.readOnly=renew;f.elements.identity_number.readOnly=renew;unit.disabled=false;$('#cheque-list').innerHTML='';if(!renew){for(let n of ['unit_id','room_show','name','contact','nationality','vat_id','identity_number','start_date','end_date','free_months','yearly_rent','commission_amount','security_amount','sewa_account','notes'])if(f.elements[n])f.elements[n].value='';f.elements.purpose.value='Family';f.elements.payment_mode.value='Cash';$('#cheque-box').classList.add('hidden')}};
  $('#lookup-tenant').onclick=async()=>{let code=f.elements.renewal_code.value.trim().toUpperCase();if(!code){toast('Enter a tenant code first.',true);return}try{let old=await api('tenant-lookup&code='+encodeURIComponent(code));if(!old.has_active||!old.tenancy_id){$('#lookup-status').textContent='Tenant found, but there is no active agreement to renew. Choose New tenancy instead.';$('#lookup-status').className='lookup-status span-2 error';f.elements.renewal_of.value='';return}f.elements.renewal_of.value=old.tenancy_id;f.elements.unit_id.value=old.unit_id;f.elements.room_show.value=`${old.property_name} · ${old.room_number}`;f.elements.name.value=old.name;f.elements.contact.value=old.contact;f.elements.nationality.value=old.nationality||'';f.elements.vat_id.value=old.vat_id||'';f.elements.identity_number.value=old.identity_number||'';f.elements.purpose.value=old.purpose;let start=new Date(old.end_date+'T00:00:00');start.setDate(start.getDate()+1);f.elements.start_date.value=dateInput(start);let end=new Date(start);end.setFullYear(end.getFullYear()+1);end.setDate(end.getDate()-1);f.elements.end_date.value=dateInput(end);f.elements.free_months.value=old.free_months||0;f.elements.yearly_rent.value=old.yearly_rent;f.elements.payment_mode.value=old.payment_mode;f.elements.commission_amount.value=old.commission_amount||0;f.elements.security_amount.value=old.security_amount||0;f.elements.sewa_account.value=old.sewa_account||'';f.elements.notes.value=old.notes||'';unit.disabled=true;$('#cheque-box').classList.toggle('hidden',old.payment_mode!=='Cheque');$('#lookup-status').textContent=`Loaded ${old.name} · ${old.property_name}, unit ${old.room_number} · last term ${date(old.start_date)} – ${date(old.end_date)}. Enter new cheques below.`;$('#lookup-status').className='lookup-status span-2 success'}catch(e){$('#lookup-status').textContent=e.message;$('#lookup-status').className='lookup-status span-2 error';f.elements.renewal_of.value=''}};
  $('#add-cheque').onclick=()=>addCheque();f.onsubmit=saveTenancy;
}
async function tenants(){let all=await api('tenants');cache.tenantRows=all;let q=$('#tenant-filter')?.value||'',rows=all.filter(x=>[x.code,x.name,x.contact,x.property_name,x.area,x.emirate,x.end_date].join(' ').toLowerCase().includes(q.toLowerCase())).sort((a,b)=>(b.status==='Active')-(a.status==='Active')||String(b.end_date||'').localeCompare(String(a.end_date||'')));$('#content').innerHTML=shell('People across your portfolio','TENANT DIRECTORY',`<div class="toolbar"><input id="tenant-filter" class="search" placeholder="Search tenant code, name, mobile, property or area" value="${esc(q)}"></div>${table(['TENANT / UNIQUE CODE','CONTACT / ID','PROPERTY / UNIT','PURPOSE','RENT','TERM','STATUS'],rows.map(x=>`<tr><td><button class="history-link" data-history="${x.id}">${esc(x.name)}</button><small class="sub-cell mono">${esc(x.code||'No code')} · Agreement #${x.tenancy_id||'—'}</small></td><td>${esc(x.contact)}<small class="sub-cell">${esc(x.identity_number||'')}</small></td><td>${esc(x.property_name||'—')} · ${esc(x.room_number||'—')}<small class="sub-cell">${esc(x.area||'')} ${esc(x.emirate||'')}</small></td><td>${esc(x.purpose||'—')}</td><td>${x.yearly_rent?money(x.yearly_rent):'—'}</td><td>${date(x.start_date)} – ${date(x.end_date)}</td><td><span class="pill ${x.status==='Active'?'green':'gray'}">${esc(x.status||'No tenancy')}</span></td></tr>`).join(''))}`);$('#tenant-filter').oninput=e=>{let v=e.target.value;tenants().then(()=>$('#tenant-filter').value=v)}}
async function saveTenancy(e){e.preventDefault();let f=e.currentTarget,renew=f.elements.agreement_type.value==='Renewal';if(renew&&(!f.elements.renewal_of.value||!f.elements.renewal_code.value)){toast('Look up the tenant code before saving a renewal.',true);return}let fd=new FormData(f);if(f.elements.unit_id.disabled)fd.set('unit_id',f.elements.unit_id.value);let cheques=[...$('#cheque-list').querySelectorAll('.cheque-row')].map(r=>Object.fromEntries([...r.querySelectorAll('[name]')].map(i=>[i.name,i.value])));fd.set('payload',JSON.stringify({cheques}));try{let res=await fetch('api.php?action=tenancy',{method:'POST',headers:{'X-CSRF':window.FORA.csrf},body:fd}),j=await res.json();if(!res.ok||j.error)throw Error(j.error);toast(j.tenant_code?`Tenancy saved · Tenant code ${j.tenant_code}`:'Renewal saved as a new tenancy record.');go('tenants')}catch(err){toast(err.message,true)}}
async function details(){let units=await api('units');cache.units=units;$('#content').innerHTML=shell('Rooms, suites & unit inventory','UNIT DETAILS',`${table(['PROPERTY','ROOM','CONFIGURATION','BATHROOMS','FLOOR','OCCUPANCY','STATUS','ACTIONS'],units.map(x=>`<tr><td><b>${esc(x.property_name)}</b><small class="sub-cell">${esc(x.area)}, ${esc(x.emirate)}</small></td><td>${esc(x.room_number)}</td><td>${esc(x.bedrooms)}</td><td>${x.bathrooms}</td><td>${esc(x.floor_label||'—')}</td><td>${esc(x.occupancy)}</td><td><span class="pill ${x.occupied?'amber':'green'}">${x.occupied?'Occupied':'Available'}</span></td><td class="unit-actions"><button class="text-button" data-unit-edit="${x.id}">Edit</button>${x.occupied?'<span class="quiet">Occupied</span>':`<button class="button button-dark button-small" data-rent-unit="${x.id}">Rent this</button>`}</td></tr>`).join(''))}`,`<button class="button button-dark" data-modal="unit">＋ Add unit</button>`)}
async function editUnit(id){let units=cache.units||await api('units'),u=units.find(x=>x.id==id),props=cache.properties||await api('properties');if(!u)return;$('#modal-root').innerHTML=`<div class="modal-backdrop"><form id="unit-edit-form" class="modal"><button type="button" class="modal-close">×</button><span class="eyebrow">UNIT INVENTORY</span><h2>Edit unit details</h2><input type="hidden" name="id" value="${u.id}"><div class="form-grid"><label class="span-2">Property<select name="property_id" required>${props.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.code)}</option>`).join('')}</select></label>${field('Room number','room_number')}${field('Bedrooms','bedrooms','select',{options:['Studio',...Array.from({length:10},(_,i)=>`${i+1} BHK`)]})}${field('Bathrooms','bathrooms','number',{min:1})}${field('Floor','floor_label','text',{required:false})}${field('Occupancy','occupancy','select',{options:['Family','Bachelor','Both']})}</div><div class="form-actions"><button class="button button-dark">Save changes</button></div></form></div>`;let f=$('#unit-edit-form');f.elements.property_id.value=u.property_id;f.elements.room_number.value=u.room_number;f.elements.bedrooms.value=u.bedrooms;f.elements.bathrooms.value=u.bathrooms;f.elements.floor_label.value=u.floor_label||'';f.elements.occupancy.value=u.occupancy;f.querySelector('.modal-close').onclick=()=>$('#modal-root').innerHTML='';f.onsubmit=async e=>{e.preventDefault();try{await api('unit-update',{method:'POST',body:Object.fromEntries(new FormData(f))});$('#modal-root').innerHTML='';toast('Unit details updated.');go('details')}catch(x){toast(x.message,true)}}}
document.addEventListener('click',async e=>{let edit=e.target.closest('[data-unit-edit]'),rent=e.target.closest('[data-rent-unit]');if(edit){editUnit(edit.dataset.unitEdit);return}if(rent){let id=rent.dataset.rentUnit,u=(cache.units||[]).find(x=>String(x.id)===String(id));await go('tenancies');let f=$('#tenancy-form');if(f?.elements.unit_id&&u){f.elements.agreement_type.value='New';f.elements.agreement_type.dispatchEvent(new Event('change'));f.elements.property_code.value=u.property_code;f.elements.property_code.dispatchEvent(new Event('change'));f.elements.property_id.value=u.property_id;f.elements.property_id.dispatchEvent(new Event('change'));f.elements.unit_id.value=id;f.elements.unit_id.dispatchEvent(new Event('change'))}}});
