async function unitEntryModal(){let props=cache.properties||await api('properties');$('#modal-root').innerHTML=`<div class="modal-backdrop"><form id="unit-entry-form" class="modal"><button type="button" class="modal-close">×</button><span class="eyebrow">UNIT INVENTORY</span><h2>Add room or units</h2><div class="form-grid"><label class="span-2">Property<select name="property_id" required>${props.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.code)}</option>`).join('')}</select></label>${field('Entry mode','entry_mode','select',{options:['Single room','Bulk range']})}<div class="span-2" id="single-room-field">${field('Room number','room_number')}</div><div class="span-2 hidden" id="bulk-range-fields"><div class="form-grid">${field('Room prefix (optional)','prefix','text',{required:false,placeholder:'For example B-'})}${field('Start number','start_number','number',{min:0})}${field('End number','end_number','number',{min:0})}</div><div class="range-preview" id="range-preview">Enter a start and end room number. Up to 100 rooms per batch.</div></div>${field('Bedrooms','bedrooms','select',{options:['Studio',...Array.from({length:10},(_,i)=>`${i+1} BHK`)]})}${field('Bathrooms','bathrooms','number',{min:1})}${field('Floor','floor_label','text',{required:false})}${field('Occupancy','occupancy','select',{options:['Family','Bachelor','Both']})}</div><div class="form-actions"><button class="button button-dark">Save unit(s)</button></div></form></div>`;let f=$('#unit-entry-form');const single=$('#single-room-field'),bulk=$('#bulk-range-fields'),preview=$('#range-preview');const updateMode=()=>{let isBulk=f.elements.entry_mode.value==='Bulk range';single.classList.toggle('hidden',isBulk);bulk.classList.toggle('hidden',!isBulk);f.elements.room_number.required=!isBulk;f.elements.start_number.required=isBulk;f.elements.end_number.required=isBulk};const makeRange=()=>{let a=f.elements.start_number.value,b=f.elements.end_number.value,prefix=f.elements.prefix.value||'';if(a===''||b===''){preview.textContent='Enter a start and end room number.';return null}let start=Number(a),end=Number(b),count=end-start+1;if(!Number.isInteger(start)||!Number.isInteger(end)||count<1||count>100){preview.textContent='End must be at or after start, with no more than 100 rooms.';return null}let width=Math.max(a.length,b.length);let numbers=Array.from({length:count},(_,i)=>prefix+String(start+i).padStart(width,'0'));preview.textContent=`${count} room${count===1?'':'s'}: ${numbers[0]} through ${numbers[numbers.length-1]}`;return numbers};f.elements.entry_mode.onchange=updateMode;for(let n of ['start_number','end_number','prefix'])f.elements[n].oninput=makeRange;f.querySelector('.modal-close').onclick=()=>$('#modal-root').innerHTML='';$('#modal-root').querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))$('#modal-root').innerHTML=''};f.onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(f)),isBulk=d.entry_mode==='Bulk range';delete d.entry_mode;try{if(isBulk){d.room_numbers=makeRange();if(!d.room_numbers)throw Error('Enter a valid room number range.');delete d.start_number;delete d.end_number;delete d.prefix;await api('unit-bulk',{method:'POST',body:d});toast(`Added ${d.room_numbers.length} rooms.`)}else{await api('unit',{method:'POST',body:d});toast('Unit saved.')}$('#modal-root').innerHTML='';go('details')}catch(x){toast(x.message,true)}};updateMode()}
async function modal(type){if(type==='unit')return unitEntryModal();if(type==='property'){let props=`<div class="modal-backdrop"><form id="modal-form" class="modal"><button type="button" class="modal-close">×</button><span class="eyebrow">PORTFOLIO</span><h2>Add a property</h2><div class="form-grid">${field('Property name','name')}${field('Property code','code')}${field('Emirate','emirate','select',{options:['Abu Dhabi','Dubai','Sharjah','Ajman','Umm Al Quwain','Ras Al Khaimah','Fujairah']})}${field('Area','area')}${field('Owner name','owner_name')}${field('Owner contact','owner_contact','tel',{required:false})}${field('Property type','type','select',{options:['Residential','Commercial','Land','Shed','Warehouse','Other']})}<label class="span-2">Address<textarea name="address" rows="2"></textarea></label></div><div class="form-actions"><button class="button button-dark">Save property</button></div></form></div>`;$('#modal-root').innerHTML=props;let f=$('#modal-form');f.querySelector('.modal-close').onclick=()=>$('#modal-root').innerHTML='';f.onsubmit=async e=>{e.preventDefault();try{await api('property',{method:'POST',body:Object.fromEntries(new FormData(f))});$('#modal-root').innerHTML='';toast('Property saved.');go('properties')}catch(x){toast(x.message,true)}}}}
async function duesPage(category){let rows=await api('dues&category='+encodeURIComponent(category));$('#content').innerHTML=shell(`${category} receipts from tenancy contracts`,category.toUpperCase(),`${table(['DATE','TENANT','PROPERTY / UNIT','DESCRIPTION','NET','VAT 5%','TOTAL','STATUS','RECEIPT','ACTIONS'],rows.map(r=>`<tr><td>${date(r.bill_date)}</td><td><b>${esc(r.tenant_name)}</b><small class="sub-cell mono">${esc(r.tenant_code)}</small></td><td>${esc(r.property_name)} · ${esc(r.room_number)}</td><td>${esc(r.description)}</td><td>${money(r.amount)}</td><td>${money(r.vat_amount)}</td><td><b>${money(r.total_amount)}</b></td><td><span class="pill ${r.status==='Paid'?'green':r.status==='Draft'?'amber':'gray'}">${esc(r.status)}</span></td><td class="mono">${esc(r.receipt_no||'—')}</td><td class="billing-actions"><button class="text-button" data-edit-due="${r.id}">Edit</button><button class="text-button" data-print-due="${r.id}">Print</button></td></tr>`).join(''))}`);document.querySelectorAll('[data-edit-due]').forEach(b=>b.onclick=()=>editDue(rows.find(x=>String(x.id)===b.dataset.editDue)));document.querySelectorAll('[data-print-due]').forEach(b=>b.onclick=()=>printReceipt(rows.find(x=>String(x.id)===b.dataset.printDue),'Receipt'))}
async function editDue(r){if(!r)return;$('#modal-root').innerHTML=`<div class="modal-backdrop"><form id="due-edit-form" class="modal"><button type="button" class="modal-close">×</button><span class="eyebrow">${esc(r.category)} RECEIPT</span><h2>Edit draft receipt</h2><div class="notice">Tenant: <b>${esc(r.tenant_name)}</b> · ${esc(r.property_name)} / ${esc(r.room_number)}</div><div class="form-grid">${field('Receipt date','bill_date','date')}${field('Description','description')}${field('Amount before VAT (AED)','amount','number',{min:0,step:'0.01'})}${field('VAT 5% (AED)','vat_amount','number',{required:false})}${field('Total amount (AED)','total_amount','number',{required:false})}${field('Status','status','select',{options:['Draft','Pending','Paid']})}${field('Paid date','paid_at','date',{required:false})}<label class="span-2">Notes<textarea name="notes" rows="3"></textarea></label></div><div class="form-actions"><button class="button button-dark">Save receipt</button></div></form></div>`;let f=$('#due-edit-form');f.elements.bill_date.value=r.bill_date||dateInput(new Date());f.elements.description.value=r.description||`${r.category} receipt`;f.elements.amount.value=r.amount;f.elements.vat_amount.value=Number(r.vat_amount||0).toFixed(2);f.elements.total_amount.value=Number(r.total_amount||0).toFixed(2);f.elements.vat_amount.readOnly=true;f.elements.total_amount.readOnly=true;f.elements.status.value=r.status;f.elements.paid_at.value=r.paid_at||dateInput(new Date());f.elements.notes.value=r.notes||'';let calc=()=>{let amount=Number(f.elements.amount.value)||0,vat=Math.round((amount*.05+Number.EPSILON)*100)/100;f.elements.vat_amount.value=vat.toFixed(2);f.elements.total_amount.value=(amount+vat).toFixed(2)};f.elements.amount.oninput=calc;f.querySelector('.modal-close').onclick=()=>$('#modal-root').innerHTML='';f.onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(f));d.id=r.id;try{await api('due-update',{method:'POST',body:d});$('#modal-root').innerHTML='';toast('Receipt saved.');go(r.category==='Commission'?'commission':'security')}catch(x){toast(x.message,true)}}}

