function renderBusinessPage(view){if(view==='office_clients'){officeClients().catch(error=>{document.querySelector('#content').innerHTML='<div class="empty">'+esc(error.message)+'</div>'});return}if(view==='office_work'){officeWorkPage().catch(error=>{document.querySelector('#content').innerHTML='<div class="empty">'+esc(error.message)+'</div>'});return}if(view==='office_packages'){officePackagesPage().catch(error=>{document.querySelector('#content').innerHTML='<div class="empty">'+esc(error.message)+'</div>'});return}if(view==='office_bills'){officeBillsPage().catch(error=>{document.querySelector('#content').innerHTML='<div class="empty">'+esc(error.message)+'</div>'});return}if(view==='office_history'){officeWorkHistoryPage().catch(error=>{document.querySelector('#content').innerHTML='<div class="empty">'+esc(error.message)+'</div>'});return}if(view==='office_wallet'){officeClientWalletPage().catch(error=>{document.querySelector('#content').innerHTML='<div class="empty">'+esc(error.message)+'</div>'});return}if(view==='office_customer_wallet'){officeCustomerWalletPage().catch(error=>{document.querySelector('#content').innerHTML=`<div class="empty">${esc(error.message)}</div>`});return}if(view==='office_tax_report'){officeTaxReportPage().catch(error=>{document.querySelector('#content').innerHTML='<div class="empty">'+esc(error.message)+'</div>'});return}if(view==='office_corporate_tax'){officeCorporateTaxPage().catch(error=>{document.querySelector('#content').innerHTML='<div class="empty">'+esc(error.message)+'</div>'});return}if(view==='office_daybook'){officeDayBookPage().catch(error=>{document.querySelector('#content').innerHTML=`<div class="empty">${esc(error.message)}</div>`});return}if(view==='office_expenses'){officeExpensesPage().catch(error=>{document.querySelector('#content').innerHTML=`<div class="empty">${esc(error.message)}</div>`});return}if(view==='office_shop_wallet'){officeShopWalletPage().catch(error=>{document.querySelector('#content').innerHTML=`<div class="empty">${esc(error.message)}</div>`});return}if(view==='mobile_overview'){openMobileOverview().catch(error=>{document.querySelector('#content').innerHTML='<div class="empty">'+esc(error.message)+'</div>'});return}let [kind,page]=view.split('_'),section=businessSections[kind],title=section.pages[page];$('#content').innerHTML=shell(title,section.label,`<div class="business-ready"><span class="business-ready-icon">${section.icon}</span><div><span class="eyebrow">${section.name.toUpperCase()} WORKSPACE</span><h2>${esc(title)}</h2><p>This page is set aside for ${esc(title.toLowerCase())} in ${esc(section.name)}. Its records will be kept separate from Real Estate.</p><span class="pill amber">Setup page</span></div></div><div class="business-page-links">${Object.entries(section.pages).map(([key,label])=>`<button class="business-page-link ${key===page?'selected':''}" data-go="${kind}_${key}"><b>${esc(label)}</b><span>Open ${esc(label.toLowerCase())} →</span></button>`).join('')}</div>`)}
go=async function(view){if(!/^(mobile|grocery|supermarket|car|restaurant|pharmacy|electronics|fashion|other|office)_/.test(view))return goBeforeBusinessSections(view);let routeSplit=view.indexOf('_'),kind=view.slice(0,routeSplit),page=view.slice(routeSplit+1),section=businessSections[kind];if(!section||!section.pages[page])return goBeforeBusinessSections(view);if(window.FORA.user.role!=='super_admin'&&!(window.FORA.user.sections||[]).includes(section.accessKey)){$('#content').innerHTML='<div class="empty">Your company does not have access to this section.</div>';return}current=view;document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view===view));let group=document.querySelector(`[data-business-group="${kind}"]`);if(group)group.open=true;$('#crumb').textContent=section.label;$('#page-title').textContent=section.pages[page];$('#content').innerHTML='<div class="loading">Loading workspace…</div>';renderBusinessPage(view)};

