async function openCompanyOverviewAction(action){switch(action){case 'mobile-sales':requestSalesmanCode('Sales',code=>openMobileSales(code));return;case 'mobile-new':openMobileInventory('new');return;case 'mobile-used':openMobileInventory('used');return;case 'mobile-stock':openMobileStockView();return;case 'mobile-purchases':requestSalesmanCode('Purchases',code=>openMobilePurchases(code));return;case 'mobile-orders':openMobilePurchaseOrders();return;case 'mobile-clients':openMobileClients();return;case 'mobile-suppliers':openMobileSuppliers();return;case 're-properties':go('properties');return;case 're-units':go('details');return;case 're-rent':go('tenancies');return;case 're-tenants':go('tenants');return;case 're-renewals':go('renewals');return;case 're-cheques':go('cheques');return;default:return}}
