function requestSalesmanCode(section,onConfirm){$('#modal-root').innerHTML=`<div class="modal-backdrop salesman-code-backdrop"><form class="modal salesman-code-modal" id="salesman-code-form"><button type="button" class="modal-close" aria-label="Close">×</button><span class="eyebrow">MOBILE · TEAM CHECKOUT</span><h2>Who is handling ${esc(section)}?</h2><p>Enter your staff code to open ${esc(section.toLowerCase())}.</p><label class="salesman-code-field">Staff code<input name="staff_code" list="salesman-code-options" autocomplete="off" required maxlength="80" placeholder="Select or enter a saved staff code"><datalist id="salesman-code-options"></datalist></label><div class="salesman-code-error" role="alert" aria-live="polite"></div><div class="form-actions"><button class="button button-outline" type="button" id="salesman-code-cancel">Cancel</button><button class="button button-dark" type="submit">Continue <span>→</span></button></div></form></div>`;let root=$('#modal-root'),form=$('#salesman-code-form'),input=form.elements.staff_code,error=root.querySelector('.salesman-code-error');let availableStaff=[];api('mobile-staff').then(rows=>{availableStaff=rows;root.querySelector('#salesman-code-options').innerHTML=rows.map(s=>'<option value="'+esc(s.staff_code)+'" label="'+esc(s.name)+'"></option>').join('');if(rows.length===1)input.value=rows[0].staff_code}).catch(()=>{});requestAnimationFrame(()=>input.focus());const close=()=>{root.innerHTML=''};root.querySelector('.modal-close').onclick=close;$('#salesman-code-cancel').onclick=close;root.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))close()};form.onsubmit=async e=>{e.preventDefault();let code=input.value.trim();if(!code){error.textContent='Enter your staff code to continue.';input.focus();return}let submit=form.querySelector('[type="submit"]');submit.disabled=true;submit.textContent='Checking…';error.textContent='';try{await api('mobile-staff-code&code='+encodeURIComponent(code));close();onConfirm(code)}catch(err){error.textContent=err.message+(availableStaff.length?' Available staff code: '+availableStaff.map(s=>s.name+' ('+s.staff_code+')').join(', '):' No staff codes are saved for this company yet.');submit.disabled=false;submit.innerHTML='Continue <span>→</span>';input.focus()}}}
async function openMobileCorporateTax(){current='mobile_corporate_tax';document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view==='mobile_corporate_tax'));document.querySelectorAll('#nav .nav-group[open]').forEach(g=>{if(g.dataset.businessGroup!=='mobile')g.open=false});let group=document.querySelector('#nav [data-business-group="mobile"]');if(group)group.open=true;$('#crumb').textContent='MOBILE · CORPORATE TAX';$('#page-title').textContent='Corporate Tax';$('#content').innerHTML='<div class="loading">Loading Corporate Tax working papers…</div>';try{let [rows,settings]=await Promise.all([api('mobile-corporate-tax'),api('company-settings')]),edit=null;const escval=(v)=>esc(v??'');const quarterPeriods=(start,end)=>{if(!start||!end||start>end)return [];const shift=(value,months,days=0)=>{let [y,m,d]=value.split('-').map(Number),b=new Date(Date.UTC(y,m-1+months,1)),last=new Date(Date.UTC(b.getUTCFullYear(),b.getUTCMonth()+1,0)).getUTCDate();b.setUTCDate(Math.min(d,last)+days);return b.toISOString().slice(0,10)};let result=[],from=start;for(let n=0;n<4;n++){let to=shift(from,3,-1);if(to>end)to=end;result.push({from,to});from=shift(to,0,1);if(from>end)break}return result};const taxDateDefault=(new Date().getFullYear()-1);const render=()=>{let r=edit||{};$('#content').innerHTML=shell('Corporate Tax working paper','MOBILE · UAE COMPLIANCE',`<section class="ct-hero"><div><span class="eyebrow">TAX PERIOD PREPARATION</span><h2>Prepare with clarity.<br><em>Keep the supporting record.</em></h2><p>Use your signed financial statements and tax reconciliation to complete each period.</p></div><div class="ct-hero-mark">CT<span>UAE</span></div></section><div class="ct-notice"><b>Preparation worksheet only.</b> This page does not submit a return to the FTA. File the official return through <a href="https://www.tax.gov.ae/en/content/corporate.tax.return.aspx" target="_blank" rel="noopener">EmaraTax / the FTA</a>. UAE Corporate Tax calculations depend on your entity type and tax adjustments. Use your accountant’s reviewed figures.</div><section class="ct-company-period-card"><div><span class="eyebrow">COMPANY PROFILE</span><h3>${esc(settings.trade_name)}${settings.arabic_trade_name?' · '+esc(settings.arabic_trade_name):''}</h3><p>${esc(settings.address||'')}${settings.address_arabic?' · '+esc(settings.address_arabic):''}</p></div><div><span class="eyebrow">CORPORATE TAX PERIOD</span><p>Separate from VAT reporting periods</p><b>${settings.corporate_tax_period_start?date(settings.corporate_tax_period_start):'Set in Settings'}${settings.corporate_tax_period_end?' – '+date(settings.corporate_tax_period_end):''}</b></div></section><form id="mobile-corporate-tax-form" class="form-card corporate-tax-form"><input type="hidden" name="id" value="${escval(r.id)}"><div class="ct-form-heading"><div><span class="eyebrow">01 · TAXABLE PERSON & PERIOD</span><h3>${r.id?'Edit':'Create'} a tax period</h3></div>${r.id?'<button type="button" class="button button-outline" id="ct-new-record">New working paper</button>':''}</div><div class="form-grid"><label>Taxable person name<input name="taxable_person_name" required maxlength="200" value="${escval(r.taxable_person_name||window.FORA.user.trade_name||'')}"></label><label>Corporate Tax TRN<input name="corporate_tax_trn" required maxlength="80" value="${escval(r.corporate_tax_trn||'')}"></label><label>Taxable person type<select name="taxable_person_type" required>${['Resident Person','Non-Resident Person','Qualifying Free Zone Person','Non-qualifying Free Zone Person','Tax Group'].map(x=>`<option ${r.taxable_person_type===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Accounting standard<select name="accounting_standard" required>${['IFRS','IFRS for SMEs','Other UAE-accepted standard'].map(x=>`<option ${r.accounting_standard===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Tax period start<input type="date" name="tax_period_start" required value="${escval(r.tax_period_start||settings.corporate_tax_period_start||`${taxDateDefault}-01-01`)}"></label><label>Tax period end<input type="date" name="tax_period_end" required value="${escval(r.tax_period_end||settings.corporate_tax_period_end||`${taxDateDefault}-12-31`)}"></label><label>Financial statements audited?<select name="audited_financial_statements"><option value="0" ${Number(r.audited_financial_statements)!==1?'selected':''}>No</option><option value="1" ${Number(r.audited_financial_statements)===1?'selected':''}>Yes</option></select></label><label>Annual revenue (AED)<input name="revenue" type="number" min="0" step="0.01" required value="${escval(r.revenue||0)}"></label></div><div class="form-section-title">02 <span>ACCOUNTING INCOME & TAX ADJUSTMENTS · AED</span></div><div class="form-grid"><label>Accounting profit / (loss)<input name="accounting_income" type="number" step="0.01" required value="${escval(r.accounting_income||0)}"><small>From the financial statements for this tax period.</small></label><label>Exempt income to deduct<input name="exempt_income" type="number" min="0" step="0.01" value="${escval(r.exempt_income||0)}"></label><label>Non-deductible expenses to add back<input name="non_deductible_expenses" type="number" min="0" step="0.01" value="${escval(r.non_deductible_expenses||0)}"><small>Enter the tax disallowance amount, not the full expense unless fully disallowed.</small></label><label>Other taxable-income additions<input name="other_additions" type="number" min="0" step="0.01" value="${escval(r.other_additions||0)}"></label><label>Other permitted deductions<input name="other_deductions" type="number" min="0" step="0.01" value="${escval(r.other_deductions||0)}"></label><label>Tax losses available from prior periods<input name="tax_losses_brought_forward" type="number" min="0" step="0.01" value="${escval(r.tax_losses_brought_forward||0)}"></label><label>Tax losses used this period<input name="tax_losses_used" type="number" min="0" step="0.01" value="${escval(r.tax_losses_used||0)}"><small>Cannot exceed available losses or 75% of pre-loss taxable income.</small></label><label id="ct-qualifying-income-wrap" class="hidden">Taxable income attributable to Qualifying Income (AED)<input name="qualifying_income" type="number" min="0" step="0.01" value="${escval(r.qualifying_income||0)}"></label><label>Foreign Tax Credits claimed<input name="foreign_tax_credits" type="number" min="0" step="0.01" value="${escval(r.foreign_tax_credits||0)}"></label></div><label class="ct-sbr-toggle"><input type="checkbox" name="claim_small_business_relief" value="1" ${Number(r.claim_small_business_relief)===1?'checked':''}><span><b>Claim Small Business Relief</b><small>Only select if you have confirmed all legal eligibility conditions for this period.</small></span></label><label id="ct-sbr-confirm-wrap" class="ct-sbr-confirm hidden"><input type="checkbox" name="sbr_confirmed" value="1"><span>I confirm the business meets the applicable Small Business Relief requirements, including prior-period revenue and exclusion conditions.</span></label><section class="ct-calculation"><div class="ct-calc-head"><div><span class="eyebrow">LIVE ESTIMATE</span><h3>Tax calculation</h3></div><span id="ct-deadline" class="ct-deadline">Filing deadline · —</span></div><div class="ct-calc-grid"><span><small>Taxable income before losses</small><b id="ct-taxable">AED 0</b></span><span><small>Tax loss relief used</small><b id="ct-loss-used">AED 0</b></span><span><small>Taxable income after losses</small><b id="ct-after-loss">AED 0</b></span><span><small>Corporate Tax liability</small><b id="ct-liability">AED 0</b></span><span><small>Corporate Tax payable</small><b id="ct-payable">AED 0</b></span></div><p id="ct-rate-note">Standard rates: 0% on the first AED 375,000 of taxable income, then 9% on the excess.</p></section><div class="form-grid"><label class="span-2">Notes<textarea name="notes" rows="3" maxlength="4000">${escval(r.notes||'')}</textarea></label></div><div class="form-actions"><button class="button button-outline" type="button" id="ct-reset">Clear form</button><button class="button button-dark">Save working paper <span>→</span></button></div></form><section class="ct-records"><div class="section-head"><div><span class="eyebrow">SAVED PERIODS</span><h2>Corporate Tax records</h2></div></div><div class="table-wrap"><table><thead><tr><th>TAX PERIOD</th><th>TAXABLE PERSON</th><th>TAXABLE INCOME</th><th>TAX PAYABLE</th><th>FILING DEADLINE</th><th>ACTIONS</th></tr></thead><tbody>${rows.length?rows.map(x=>`<tr><td>${date(x.tax_period_start)} – ${date(x.tax_period_end)}</td><td><b>${esc(x.taxable_person_name)}</b><small class="sub-cell">${esc(x.corporate_tax_trn)} · ${esc(x.taxable_person_type)}</small></td><td>${money(x.taxable_income)}</td><td><b>${money(x.corporate_tax_payable)}</b></td><td>${date(x.filing_deadline)}</td><td class="billing-actions"><button class="text-button" type="button" data-ct-edit="${x.id}">Edit</button><button class="text-button" type="button" data-ct-print="${x.id}">Print</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty-cell">No Corporate Tax periods saved yet</td></tr>'}</tbody></table></div></section><p class="ct-footnote">The FTA return may require additional schedules, elections, disclosures, and supporting calculations that depend on your circumstances.</p>`);let form=$('#mobile-corporate-tax-form'),type=form.elements.taxable_person_type,claim=form.elements.claim_small_business_relief,confirmWrap=$('#ct-sbr-confirm-wrap'),qualWrap=$('#ct-qualifying-income-wrap');const amount=k=>Number(form.elements[k].value)||0;const calc=()=>{qualWrap.classList.toggle('hidden',type.value!=='Qualifying Free Zone Person');let taxable=amount('accounting_income')-amount('exempt_income')+amount('non_deductible_expenses')+amount('other_additions')-amount('other_deductions'),maxLoss=Math.min(amount('tax_losses_brought_forward'),Math.max(0,taxable)*.75);let lossUsed=Math.min(amount('tax_losses_used'),maxLoss),after=taxable-lossUsed,revenue=amount('revenue'),end=form.elements.tax_period_end.value,sbrPossible=type.value==='Resident Person'&&revenue<=3000000&&form.elements.tax_period_start.value>='2023-06-01'&&end<='2029-12-31';confirmWrap.classList.toggle('hidden',!claim.checked);let sbr=claim.checked&&sbrPossible&&form.elements.sbr_confirmed.checked,liability=sbr?0:type.value==='Qualifying Free Zone Person'?Math.max(0,after-amount('qualifying_income'))*.09:Math.max(0,after-375000)*.09,payable=Math.max(0,liability-amount('foreign_tax_credits'));$('#ct-taxable').textContent=money(taxable);$('#ct-loss-used').textContent=money(lossUsed);$('#ct-after-loss').textContent=money(after);$('#ct-liability').textContent=money(liability);$('#ct-payable').textContent=money(payable);let endDate=form.elements.tax_period_end.value;$('#ct-deadline').textContent='Filing deadline · '+(endDate?date(addNineMonthsEnd(endDate)):'—');$('#ct-rate-note').textContent=type.value==='Qualifying Free Zone Person'?'Qualifying income is taxed at 0%; other taxable income is taxed at 9%.':'Standard rate: 0% on the first AED 375,000 of taxable income, then 9% on the excess.';let hint=$('#ct-sbr-hint');if(!sbrPossible&&claim.checked){if(!hint){hint=document.createElement('p');hint.id='ct-sbr-hint';hint.className='ct-sbr-hint';claim.parentElement.after(hint)}hint.textContent='Current inputs do not meet the basic period, person-type, or AED 3 million revenue limits.'}else if(hint)hint.remove()};const addNineMonthsEnd=value=>{let [y,m,d]=value.split('-').map(Number),first=new Date(y,m-1+9,1),last=new Date(first.getFullYear(),first.getMonth()+1,0).getDate();return `${first.getFullYear()}-${String(first.getMonth()+1).padStart(2,'0')}-${String(Math.min(d,last)).padStart(2,'0')}`};form.querySelectorAll('input,select').forEach(x=>x.addEventListener('input',calc));type.onchange=calc;claim.onchange=calc;if(r.id)form.elements.sbr_confirmed.checked=Number(r.claim_small_business_relief)===1;calc();$('#ct-reset').onclick=()=>{edit=null;render()};let newButton=$('#ct-new-record');if(newButton)newButton.onclick=()=>{edit=null;render()};form.onsubmit=async e=>{e.preventDefault();let body=Object.fromEntries(new FormData(form));body.audited_financial_statements=Number(body.audited_financial_statements||0);body.claim_small_business_relief=claim.checked?1:0;body.sbr_confirmed=form.elements.sbr_confirmed.checked?1:0;try{let saved=await api('mobile-corporate-tax-save',{method:'POST',body});toast(`Tax working paper saved · payable ${money(saved.corporate_tax_payable)}`);openMobileCorporateTax()}catch(error){toast(error.message,true)}};document.querySelectorAll('[data-ct-edit]').forEach(b=>b.onclick=()=>{edit=rows.find(x=>String(x.id)===b.dataset.ctEdit);render();$('#content').scrollIntoView({behavior:'smooth',block:'start'})});document.querySelectorAll('[data-ct-print]').forEach(b=>b.onclick=()=>{let x=rows.find(r=>String(r.id)===b.dataset.ctPrint);if(x)printCorporateTaxRecord(x)})};render()}catch(error){document.querySelector('#content').innerHTML='<div class="empty">'+esc(error.message)+'</div>'}}
function printCorporateTaxRecord(x){let w=window.open('','_blank');if(!w){toast('Allow pop-ups to print this record.',true);return}let rows=[['Taxable person',x.taxable_person_name],['Corporate Tax TRN',x.corporate_tax_trn],['Taxable person type',x.taxable_person_type],['Tax period',`${date(x.tax_period_start)} – ${date(x.tax_period_end)}`],['Accounting standard',x.accounting_standard],['Annual revenue',money(x.revenue)],['Accounting profit / (loss)',money(x.accounting_income)],['Exempt income',money(x.exempt_income)],['Non-deductible expenses',money(x.non_deductible_expenses)],['Other additions',money(x.other_additions)],['Other deductions',money(x.other_deductions)],['Tax losses used',money(x.tax_losses_used)],['Taxable income before losses',money(x.taxable_income_before_losses)],['Taxable income after losses',money(x.taxable_income)],['Tax liability',money(x.tax_liability)],['Foreign Tax Credits',money(x.foreign_tax_credits)],['Corporate Tax payable',money(x.corporate_tax_payable)],['Filing deadline',date(x.filing_deadline)],['Notes',x.notes||'—']];w.document.write(`<html><head><title>Corporate Tax working paper</title><style>body{font:14px Arial;color:#172722;padding:35px}h1{color:#244636}table{border-collapse:collapse;width:100%;margin-top:25px}td{padding:10px;border-bottom:1px solid #ddd}td:first-child{font-weight:bold;width:40%}.mark{color:#777;margin-top:22px;font-size:12px}</style></head><body><h1>Corporate Tax working paper</h1><p>Internal preparation record · not an FTA filing</p><table>${rows.map(([a,b])=>`<tr><td>${esc(a)}</td><td>${esc(b)}</td></tr>`).join('')}</table><p class="mark">Verify all figures and schedules before filing through EmaraTax.</p><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}
