async function openMobileProducts(){current='mobile_products';document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view==='mobile_products'));document.querySelectorAll('#nav .nav-group[open]').forEach(g=>{if(g.dataset.businessGroup!=='mobile')g.open=false});let group=document.querySelector('#nav [data-business-group="mobile"]');if(group)group.open=true;let business=[...document.querySelectorAll('.mobile-nav-group')].find(x=>x.querySelector('[data-view="mobile_products"]'));if(business)business.open=true;$('#crumb').textContent='MOBILE · STOCK';$('#page-title').textContent='Products & stock';$('#content').innerHTML='<div class="loading">Loading stock…</div>';try{let [fresh,used]=await Promise.all([api('mobile-inventory&type=new'),api('mobile-inventory&type=used')]),all=[...fresh.map(x=>({...x,entry_kind:'New'})),...used.map(x=>({...x,entry_kind:'Used'}))];let search='',kind='All';const draw=()=>{let rows=all.filter(x=>(kind==='All'||x.entry_kind===kind)&&x.stock_status==='In Stock'&&[x.item_name,x.model,x.imei_number,x.seller_name,x.stock_status].join(' ').toLowerCase().includes(search.toLowerCase()));let available=all.filter(x=>x.stock_status==='In Stock'),stockCost=available.reduce((n,x)=>n+Number(x.purchase_amount),0),potential=available.reduce((n,x)=>n+Number(x.sale_amount),0);$('#content').innerHTML=shell('A live view of every device','MOBILE · STOCK',`<section class="mobile-stock-hero"><div><span class="eyebrow">INVENTORY SNAPSHOT</span><h2>Know what’s in stock.<br><em>At a glance.</em></h2><p>Browse new and used devices, availability, IMEI, and pricing.</p></div><div class="stock-hero-value"><small>AVAILABLE STOCK COST</small><b>${money(stockCost)}</b><span>Potential sale value ${money(potential)}</span></div></section><div class="stock-stat-grid"><article><small>In stock</small><b>${available.length}</b></article><article><small>Available stock cost</small><b>${money(stockCost)}</b></article><article><small>Potential sale value</small><b>${money(potential)}</b></article><article><small>Stock items shown</small><b>${available.length}</b></article></div><div class="stock-toolbar"><input id="mobile-stock-search" class="search" placeholder="Search item, model, IMEI, or owner" value="${esc(search)}"><select id="mobile-stock-kind"><option ${kind==='All'?'selected':''}>All</option><option ${kind==='New'?'selected':''}>New</option><option ${kind==='Used'?'selected':''}>Used</option></select><button type="button" class="button button-outline" data-stock-add="new">＋ New device</button><button type="button" class="button button-dark stock-used-button" data-stock-add="used">＋ Used device</button></div><div class="table-wrap mobile-stock-table"><table><thead><tr><th>DEVICE</th><th>TYPE</th><th>IMEI</th><th>STATUS</th><th>BUY COST</th><th>SALE PRICE</th><th>PROFIT</th><th>ACTION</th></tr></thead><tbody>${rows.length?rows.map(x=>`<tr><td><b>${esc(x.item_name)}</b><small class="sub-cell">${esc(x.seller_name||'')}</small></td><td><span class="stock-kind-pill ${x.entry_kind==='Used'?'used':''}">${x.entry_kind}</span></td><td class="mono">${esc(x.imei_number)}</td><td><span class="pill ${x.stock_status==='In Stock'?'green':x.stock_status==='Reserved'?'amber':'gray'}">${esc(x.stock_status)}</span></td><td>${money(x.purchase_amount)}</td><td>${money(x.sale_amount)}</td><td>${money(x.profit_amount)}</td><td><button type="button" class="text-button" data-stock-edit="${x.id}" data-stock-kind="${x.entry_kind.toLowerCase()}">Edit</button></td></tr>`).join(''):'<tr><td colspan="8" class="empty-cell">No devices match this filter</td></tr>'}</tbody></table></div>`);$('#mobile-stock-search').oninput=e=>{search=e.target.value;draw()};$('#mobile-stock-kind').onchange=e=>{kind=e.target.value;draw()};document.querySelectorAll('[data-stock-add]').forEach(b=>b.onclick=()=>openMobileInventory(b.dataset.stockAdd));document.querySelectorAll('[data-stock-edit]').forEach(b=>b.onclick=async()=>{let id=b.dataset.stockEdit,type=b.dataset.stockKind;await openMobileInventory(type);document.querySelector(`[data-mobile-inventory-edit="${id}"]`)?.click()})};draw()}catch(error){document.querySelector('#content').innerHTML='<div class="empty">'+esc(error.message)+'</div>'}}
