async function subscriptionPage(){let d=await api('subscription-info'),exp=d.subscription_expires_at,days=exp?Math.max(0,Math.ceil((new Date(exp+'T00:00:00')-new Date(new Date().toDateString()))/86400000)):0,pending=d.requests.find(x=>x.status==='pending_review'||x.status==='awaiting_payment');$('#crumb').textContent='COMPANY · SUBSCRIPTION';$('#page-title').textContent='Subscription';let rows=d.requests.map(r=>'<tr><td><b>'+esc(r.request_number)+'</b></td><td>'+esc(r.requested_mode)+'</td><td><span class="subscription-status '+esc(r.status)+'">'+esc(({pending_review:'Waiting for approval',awaiting_payment:'Approved · waiting for payment',paid:'Paid · subscription active',rejected:'Request declined',cancelled:'Cancelled'})[r.status]||r.status)+'</span></td><td>'+date(r.requested_at.slice(0,10))+'</td><td>'+(r.paid_at?date(r.paid_at.slice(0,10)):'—')+'</td><td>'+(r.subscription_expires_at?date(r.subscription_expires_at):'—')+'</td></tr>').join('');$('#content').innerHTML='<section class="subscription-hero"><div><span class="eyebrow">YOUR COMPANY PLAN</span><h2>Keep your business<br><em>moving forward.</em></h2><p>Your plan changes only after approval and payment confirmation.</p></div><div class="subscription-hero-stat"><span>SUBSCRIPTION BALANCE</span><b>'+days+'</b><small>days remaining</small></div></section><div class="subscription-summary"><article><small>COMPANY</small><b>'+esc(d.trade_name)+'</b></article><article><small>COMPANY CODE</small><b>'+esc(d.company_code)+'</b></article><article><small>CURRENT PLAN</small><b>'+esc((d.subscription_mode||'—').toUpperCase())+'</b></article><article><small>EXPIRES</small><b>'+date(exp)+'</b></article></div>'+(pending?'<div class="subscription-pending"><span>◷</span><div><b>Request '+esc(pending.request_number)+' is '+esc(pending.status==='pending_review'?'Waiting for approval':'Approved · waiting for payment')+'</b><small>'+(pending.status==='pending_review'?'Your request is waiting for approval.':'Your request is approved. Please complete payment to activate the subscription.')+'</small></div><form id="subscription-cancel-form"><input type="hidden" name="request_id" value="'+esc(pending.id)+'"><button class="button button-light" type="submit">Cancel request</button></form></div>':'<section class="subscription-request-card"><div><span class="eyebrow">PLAN CHANGE</span><h3>Choose your subscription</h3><p>Select a plan to review the terms before submitting a request.</p></div><div class="subscription-plan-options"><label class="subscription-plan-option"><input type="radio" name="plan_choice" value="monthly" checked><span><b>Monthly</b><small>Rate to be announced</small></span></label><label class="subscription-plan-option"><input type="radio" name="plan_choice" value="yearly"><span><b>Yearly</b><small>Rate to be announced</small></span></label></div><button class="button button-dark" id="subscription-continue" type="button">Review terms <span>→</span></button></section><section class="subscription-terms-card" id="subscription-terms" hidden><span class="eyebrow">SUBSCRIPTION TERMS</span><h3>Terms and conditions</h3><div class="subscription-terms-copy"><p>Terms and conditions will be added here.</p><p>Please review the final terms before agreeing and submitting a subscription request.</p></div><form id="subscription-request-form"><input type="hidden" name="subscription_mode" value="monthly"><label class="subscription-terms-agree"><input type="checkbox" name="agree_terms" required><span>I have read and agree to the subscription terms and conditions.</span></label><div class="form-actions"><button class="button button-light" id="subscription-back" type="button">Back to plans</button><button class="button button-dark">Agree and submit request <span>→</span></button></div></form></section>')+'<div class="section-head subscription-history-head"><div><span class="eyebrow">TRACK YOUR REQUESTS</span><h2>Subscription history</h2></div></div>'+table(['REQUEST NUMBER','REQUESTED PLAN','STATUS','SUBMITTED','PAYMENT','NEW EXPIRY'],rows);let continueButton=$('#subscription-continue'),terms=$('#subscription-terms'),planCard=document.querySelector('.subscription-plan-options');if(continueButton)continueButton.onclick=()=>{let plan=document.querySelector('[name="plan_choice"]:checked');if(!plan)return;terms.hidden=false;planCard.closest('.subscription-request-card').hidden=true;terms.dataset.plan=plan.value};let back=$('#subscription-back');if(back)back.onclick=()=>{terms.hidden=true;planCard.closest('.subscription-request-card').hidden=false};let f=$('#subscription-request-form');if(f)f.onsubmit=async e=>{e.preventDefault();if(!f.elements.agree_terms.checked)return;try{let result=await api('subscription-request',{method:'POST',body:{subscription_mode:terms.dataset.plan,terms_accepted:true}});toast('Request submitted · '+result.request_number);subscriptionPage()}catch(error){toast(error.message,true)}};let cancel=$('#subscription-cancel-form');if(cancel)cancel.onsubmit=async e=>{e.preventDefault();if(!confirm('Cancel this subscription request?'))return;try{await api('subscription-request-cancel',{method:'POST',body:{request_id:cancel.elements.request_id.value}});toast('Subscription request cancelled.');subscriptionPage()}catch(error){toast(error.message,true)}}}async function subscriptionRequestsPage(){let rows=await api('subscription-requests');$('#crumb').textContent='MANAGEMENT · PAYMENT REQUESTS';$('#page-title').textContent='Payment requests';let cards=rows.map(r=>'<article class="upgrade-request-card"><header><div><span class="eyebrow">'+esc(r.request_number)+'</span><h3>'+esc(r.trade_name)+'</h3><p>'+esc(r.company_code)+' · Current: '+esc(r.current_mode)+' · Requested: <b>'+esc(r.requested_mode)+'</b></p></div><span class="subscription-status '+esc(r.status)+'">'+esc(r.status.replace('_',' '))+'</span></header><div class="upgrade-request-meta"><span><small>SUBMITTED</small><b>'+date(r.requested_at.slice(0,10))+'</b></span><span><small>CURRENT EXPIRY</small><b>'+date(r.current_subscription_expires_at)+'</b></span><span><small>REQUESTED BY COMPANY</small><b>'+esc(r.requested_mode.toUpperCase())+'</b></span></div>'+(r.status==='pending_review'?'<div class="upgrade-review-actions"><button type="button" class="button button-outline" data-upgrade-review="rejected" data-request-id="'+r.id+'">Reject request</button><button type="button" class="button button-dark" data-upgrade-review="approved" data-request-id="'+r.id+'">Approve for payment <span>→</span></button></div>':'')+(r.status==='awaiting_payment'?'<form class="upgrade-payment-form" data-request-id="'+r.id+'"><label>Amount paid (AED)<input name="paid_amount" type="number" min="0.01" step="0.01" required></label><label>Bill / receipt number<input name="bill_number" required maxlength="100"></label><label class="span-2">Bank transfer details<input name="bank_transfer_details" maxlength="500" placeholder="Bank, transfer reference, date"></label><div class="span-2"><button class="button button-dark">Record payment and activate plan <span>→</span></button></div></form>':'')+(r.status==='paid'?'<div class="upgrade-paid-note">Payment recorded · '+money(r.paid_amount)+' · '+esc(r.bill_number||'')+' · Active until '+date(r.subscription_expires_at)+'</div>':'')+'</article>').join('');$('#content').innerHTML='<section class="subscription-hero payment-hero"><div><span class="eyebrow">SUPER ADMIN</span><h2>Subscription<br><em>payment requests.</em></h2><p>Review requested plans, approve them for payment, then record payment to activate the new subscription period.</p></div><div class="subscription-hero-stat"><span>OPEN REQUESTS</span><b>'+rows.filter(x=>['pending_review','awaiting_payment'].includes(x.status)).length+'</b><small>need attention</small></div></section><div class="upgrade-request-list">'+(cards||'<div class="empty">No subscription requests yet.</div>')+'</div>';document.querySelectorAll('[data-upgrade-review]').forEach(b=>b.onclick=async()=>{try{await api('subscription-review',{method:'POST',body:{request_id:b.dataset.requestId,status:b.dataset.upgradeReview}});toast(b.dataset.upgradeReview==='approved'?'Approved. It is now under payment requests.':'Request rejected.');subscriptionRequestsPage()}catch(error){toast(error.message,true)}});document.querySelectorAll('.upgrade-payment-form').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{await api('subscription-payment',{method:'POST',body:{request_id:f.dataset.requestId,...Object.fromEntries(new FormData(f))}});toast('Payment recorded and subscription updated.');subscriptionRequestsPage()}catch(error){toast(error.message,true)}})}
document.addEventListener('click',e=>{let item=e.target.closest('#nav [data-view="subscription"],#nav [data-view="subscription_requests"],.sidebar-subscription [data-view="subscription"]');if(!item)return;e.preventDefault();e.stopImmediatePropagation();let view=item.dataset.view;if(view==='subscription'&&window.FORA.user.role!=='admin'&&window.FORA.user.role!=='super_admin'){toast('Admin access is required.',true);return}if(view==='subscription_requests'&&window.FORA.user.role!=='super_admin'){toast('Super Admin access is required.',true);return}document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n===item));document.querySelectorAll('#nav .nav-group[open]').forEach(g=>{if(g.dataset.businessGroup!=='management')g.open=false});$('#content').innerHTML='<div class="loading">Loading subscription details…</div>';try{(view==='subscription'?subscriptionPage():subscriptionRequestsPage()).catch(error=>{$('#content').innerHTML='<div class="empty">'+esc(error.message)+'</div>'})}catch(error){$('#content').innerHTML='<div class="empty">'+esc(error.message)+'</div>'}},true);
