const navIconPaths={"layout":"<rect x=\"3\" y=\"3\" width=\"7\" height=\"7\" rx=\"1\"/><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\" rx=\"1\"/><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\" rx=\"1\"/><rect x=\"14\" y=\"14\" width=\"7\" height=\"7\" rx=\"1\"/>","people":"<path d=\"M16 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2\"/><circle cx=\"10\" cy=\"7\" r=\"4\"/><path d=\"M20 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75\"/>","phone":"<rect x=\"6\" y=\"2\" width=\"12\" height=\"20\" rx=\"2\"/><path d=\"M11 18h2\"/>","cart":"<circle cx=\"9\" cy=\"21\" r=\"1\"/><circle cx=\"20\" cy=\"21\" r=\"1\"/><path d=\"M1 1h4l2.7 13.4a2 2 0 0 0 2 1.6h9.7a2 2 0 0 0 2-1.6L23 6H6\"/>","wallet":"<rect x=\"3\" y=\"5\" width=\"18\" height=\"15\" rx=\"2\"/><path d=\"M3 8h16a2 2 0 0 1 2 2v2h-5a2 2 0 0 0 0 4h5\"/><path d=\"M17 14h.01\"/>","file":"<path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><path d=\"M14 2v6h6M8 13h8M8 17h8\"/>","chart":"<path d=\"M3 3v18h18\"/><path d=\"m19 9-5 5-4-4-5 5\"/>","user":"<circle cx=\"12\" cy=\"8\" r=\"4\"/><path d=\"M5 21a7 7 0 0 1 14 0\"/>","home":"<path d=\"m3 10 9-7 9 7\"/><path d=\"M5 9v12h14V9M9 21v-7h6v7\"/>","box":"<path d=\"m12 3 9 5-9 5-9-5 9-5Z\"/><path d=\"m3 8 9 5 9-5M3 8v9l9 5 9-5V8M12 13v9\"/>","refresh":"<path d=\"M20 7v5h-5M4 17v-5h5\"/><path d=\"M5.6 9A7 7 0 0 1 18 6l2 6M4 12l2 6a7 7 0 0 0 12.4-3\"/>","briefcase":"<rect x=\"3\" y=\"7\" width=\"18\" height=\"14\" rx=\"2\"/><path d=\"M8 7V4h8v3M3 12h18M10 12v2h4v-2\"/>","gear":"<circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"m19 15 2 1-2 4-2-1-2 1v2h-5v-2l-2-1-2 1-2-4 2-1v-2l-2-1 2-4 2 1 2-1V6h5v2l2 1 2-1 2 4-2 1z\"/>"};
(function addSidebarNavIcons(){const choose=key=>{key=String(key||'').toLowerCase();if(/dashboard|overview|menu_overview/.test(key))return 'layout';if(/client|supplier|customer/.test(key))return 'people';if(/sale/.test(key))return /return/.test(key)?'refresh':'cart';if(/purchase/.test(key))return 'briefcase';if(/wallet|deposit|topup/.test(key))return 'wallet';if(/bill|invoice|receipt|cheque|payment/.test(key))return 'file';if(/tax|report|history|daybook/.test(key))return 'chart';if(/staff|user|team/.test(key))return 'user';if(/setting/.test(key))return 'gear';if(/property|tenant|rent|room|vehicle/.test(key))return 'home';if(/stock|product|mobile|inventory|work|package/.test(key))return /mobile|phone/.test(key)?'phone':'box';return 'briefcase'};document.querySelectorAll('#nav .nav-item[data-view]').forEach(button=>{if(button.querySelector('.sidebar-nav-icon'))return;const old=button.firstElementChild;if(old&&old.tagName==='SPAN')old.remove();const icon=document.createElement('span');icon.className='sidebar-nav-icon';icon.setAttribute('aria-hidden','true');icon.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">'+(navIconPaths[choose(button.dataset.view)]||navIconPaths.briefcase)+'</svg>';button.insertBefore(icon,button.firstChild)})})();
